from __future__ import annotations

import json
import sys
from pathlib import Path

import numpy as np
import xarray as xr


TASK_DIR = Path(__file__).resolve().parent
SOURCE = TASK_DIR / "source"
FIXTURE = TASK_DIR / "fixtures" / "public_case.json"
OUTPUT = TASK_DIR / "outputs" / "public_reproduction_report.json"


def _write(report: dict[str, object], code: int) -> int:
    OUTPUT.parent.mkdir(exist_ok=True)
    OUTPUT.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(json.dumps(report, indent=2, sort_keys=True))
    return code


def _dataset(case: dict[str, object]) -> xr.Dataset:
    return xr.Dataset(
        {
            "temperature": (
                ("model_level", "south_north", "west_east"),
                np.asarray(case["temperature_k"], dtype=float),
                {"units": "K", "standard_name": "air_temperature"},
            ),
            "relative_humidity": (
                ("model_level", "south_north", "west_east"),
                np.asarray(case["relative_humidity_percent"], dtype=float),
                {"units": "percent", "standard_name": "relative_humidity"},
            ),
            "air_pressure": (
                ("model_level", "south_north", "west_east"),
                np.asarray(case["pressure_hpa"], dtype=float),
                {"units": "hPa", "standard_name": "air_pressure"},
            ),
        },
        coords={
            "model_level": (
                ("model_level",),
                np.asarray(case["model_levels"], dtype=float),
                {
                    "units": "dimensionless",
                    "axis": "Z",
                    "standard_name": "atmosphere_sigma_coordinate",
                },
            )
        },
    )


def _validate_fixture(data: xr.Dataset, level_count: int) -> None:
    required = {"temperature", "relative_humidity", "air_pressure"}
    if not required.issubset(data.data_vars):
        raise ValueError("fixture is missing an atmospheric state field")
    if level_count < 1 or any(variable.size == 0 for variable in data.data_vars.values()):
        raise ValueError("fixture contains an empty scientific input")
    if not all(np.isfinite(variable.values).all() for variable in data.data_vars.values()):
        raise ValueError("fixture contains a non-finite scientific input")


def _finite_count(data: xr.DataArray) -> int:
    return int(np.isfinite(data.metpy.unit_array.magnitude).sum())


def main() -> int:
    sys.path.insert(0, str(SOURCE))
    try:
        from metpy.calc import isentropic_interpolation_as_dataset
        from metpy.units import units

        case = json.loads(FIXTURE.read_text(encoding="utf-8"))
        data = _dataset(case)
        levels = np.asarray(case["isentropic_levels_k"], dtype=float) * units.kelvin
        _validate_fixture(data, levels.size)
    except Exception as exc:
        return _write(
            {
                "schema_version": "0.2",
                "offline": True,
                "status": "runner_failure",
                "failure_kind": "setup_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    try:
        result = isentropic_interpolation_as_dataset(
            levels,
            data.temperature,
            data.air_pressure,
            data.relative_humidity,
        )
    except (TypeError, ValueError) as exc:
        return _write(
            {
                "schema_version": "0.2",
                "offline": True,
                "status": "pre_fix_expected_failure",
                "failure_kind": "scientific_workflow_unavailable",
                "workflow": "terrain_following_isentropic_analysis",
                "workflow_completed": False,
                "error_type": type(exc).__name__,
                "input_shape": list(data.temperature.shape),
                "requested_surface_count": int(levels.size),
                "finite_input_fraction": 1.0,
            },
            1,
        )
    except Exception as exc:
        return _write(
            {
                "schema_version": "0.2",
                "offline": True,
                "status": "runner_failure",
                "failure_kind": "unexpected_execution_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    try:
        required = ("pressure", "temperature", "relative_humidity")
        missing = [name for name in required if name not in result]
        finite_counts = {
            name: _finite_count(result[name]) for name in required if name in result
        }
        output_sizes = {name: int(size) for name, size in result.sizes.items()}
        output_units = {
            name: str(result[name].metpy.units) for name in required if name in result
        }
        success = (
            isinstance(result, xr.Dataset)
            and not missing
            and "isentropic_level" in result.dims
            and result.sizes["isentropic_level"] == levels.size
            and all(count > 0 for count in finite_counts.values())
        )
    except Exception as exc:
        return _write(
            {
                "schema_version": "0.2",
                "offline": True,
                "status": "runner_failure",
                "failure_kind": "result_inspection_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    report = {
        "schema_version": "0.2",
        "offline": True,
        "workflow": "terrain_following_isentropic_analysis",
        "workflow_completed": True,
        "input_shape": list(data.temperature.shape),
        "requested_surface_count": int(levels.size),
        "output_sizes": output_sizes,
        "output_units": output_units,
        "finite_output_counts": finite_counts,
        "missing_outputs": missing,
    }
    if success:
        report.update(status="post_fix_success", failure_kind=None)
        return _write(report, 0)
    report.update(status="runner_failure", failure_kind="invalid_or_empty_scientific_result")
    return _write(report, 2)


if __name__ == "__main__":
